import axios from 'axios';

// The REACT_APP_BACKEND_URL already includes /api
const API = process.env.REACT_APP_BACKEND_URL || 'http://localhost:8000/api';

// Test API connection
export const testApiConnection = async () => {
  try {
    console.log('Testing API connection...');
    
    // Test the root endpoint
    const rootResponse = await axios.get(`${API.replace('/api', '')}/api-info`);
    console.log('Root endpoint response:', rootResponse.data);
    
    // Test the login endpoint with invalid credentials (should get 401)
    try {
      const loginResponse = await axios.post(`${API}/auth/login`, {
        identifier: 'test@example.com',
        password: 'wrongpassword',
        user_type: 'student'
      });
      console.log('Login response:', loginResponse.data);
    } catch (error) {
      console.log('Login error (expected):', error.response?.data || error.message);
    }
    
    return true;
  } catch (error) {
    console.error('API connection test failed:', error);
    return false;
  }
};